package org.sleepwell.app;

import android.app.*;import android.content.*;import android.os.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.File;import java.time.*;import java.util.*;import java.util.function.Supplier;import static org.junit.Assert.*;

/** Actual saved-record flow and view persistence, private factories only; no hardware or alarm UI. */
public final class RecordInsightsFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);RecordInsightsActivity activity;
    void await(String description)throws Exception{assertTrue(description,d.wait(Until.hasObject(By.desc(description)),8000));}
    void click(String description)throws Exception{UiObject2 found=d.findObject(By.desc(description));if(found==null)found=d.findObject(By.text(description));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(description));found=d.wait(Until.findObject(By.text(description)),5000);if(found==null)found=d.findObject(By.desc(description));}assertNotNull(description,found);found.click();d.waitForIdle();}
    void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(RecordInsightsActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,RecordInsightsActivity.class).putExtra("anchor","2026-10-25").putExtra("visualReview",true).putExtra("verificationLabel","Private recorded-period fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(RecordInsightsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}}
    void finish()throws Exception{RecordInsightsActivity old=activity;i.runOnMainSync(old::finish);i.waitForIdleSync();old.awaitReaders(8000);}
    void capture(String suffix)throws Exception{i.waitForIdleSync();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"record-insights-"+suffix+".png")));}
    @Test public void realRangeActionGoalChartRecreationHistoryAndReopenPreservePrivateData()throws Exception{String name="insight-flow-"+UUID.randomUUID(),settingsName=name+"-view",plansName=name+"-plans";Records.Factory oldRecords=Records.factory;RecordInsightSettings.Factory oldSettings=RecordInsightSettings.factory;RecordInsightSettings.Cutoff oldCutoff=RecordInsightSettings.cutoff;SleepPlans.Factory oldPlans=SleepPlans.factory;Supplier<Instant> oldClock=RecordInsightsActivity.clock;Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());SharedPreferences settings=c.getSharedPreferences(settingsName,0),plans=c.getSharedPreferences(plansName,0);List<Activity> owned=new ArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof RecordInsightsActivity||a instanceof HistoryActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{assertTrue(settings.edit().putInt("days",7).commit());Records.factory=context->new Store(context,name);RecordInsightSettings.factory=context->settings;RecordInsightSettings.cutoff=context->0;SleepPlans.factory=context->plans;RecordInsightsActivity.clock=()->Instant.parse("2026-10-26T18:00:00Z");long now=RecordInsightsActivity.clock.get().toEpochMilli();try(Store store=new Store(c,name)){for(int n=0;n<6;n++){long start=LocalDate.of(2026,10,19+n).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();RecordDraft draft=new RecordDraft(start,start+(n<3?7:8)*3600000L);if(n<3)draft.addTag("Coffee");Records.create(store,draft,ZoneId.of("UTC"),now);}}SleepPlans.repository(c).add(new GoalCommitment("24ef02c0-937e-4d72-acef-b835ec377021","duration",480,LocalDate.of(2026,10,19),14,"UTC",0,"",null));String before;try(Store store=new Store(c,name)){before=store.backup().toString();}launch();await("Insight coverage 6 of 7 days");capture("week");click("Goal balance");assertTrue(d.wait(Until.hasObject(By.descStartsWith("Dated goal balance chart.")),5000));capture("goals");click("90 days");await("Insight coverage 6 of 90 days");assertEquals(90,settings.getInt("days",0));Instrumentation.ActivityMonitor monitor=i.addMonitor(RecordInsightsActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(RecordInsightsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await("Insight coverage 6 of 90 days");assertTrue(d.hasObject(By.descStartsWith("Dated goal balance chart.")));capture("reopened");
        monitor=i.addMonitor(HistoryActivity.class.getName(),null,false);HistoryActivity history;try{click("Review saved records");history=(HistoryActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(history);}finally{i.removeMonitor(monitor);}history.awaitReaders(8000);i.runOnMainSync(history::finish);history.awaitReaders(8000);finish();launch();await("Insight coverage 6 of 90 days");try(Store store=new Store(c,name)){assertEquals(before,store.backup().toString());store.eraseHistory();}finish();launch();await("Insight coverage 0 of 90 days");assertTrue(d.hasObject(By.text("No completed periods in this range")));capture("empty");finish();assertTrue(settings.edit().putInt("days",365).commit());launch();assertTrue(d.wait(Until.hasObject(By.text("Saved insight range needs attention")),8000));click("Use 30-day view");await("Insight coverage 0 of 30 days");assertEquals(30,settings.getInt("days",0));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertEquals(original,Prefs.of(c).getAll());
        }finally{for(Activity a:owned)i.runOnMainSync(()->{if(!a.isDestroyed())a.finish();});i.waitForIdleSync();for(Activity a:owned)if(a instanceof RecordInsightsActivity screen)screen.awaitReaders(8000);else if(a instanceof HistoryActivity history)history.awaitReaders(8000);app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=oldRecords;RecordInsightSettings.factory=oldSettings;RecordInsightSettings.cutoff=oldCutoff;SleepPlans.factory=oldPlans;RecordInsightsActivity.clock=oldClock;c.deleteDatabase(name);c.deleteSharedPreferences(settingsName);c.deleteSharedPreferences(plansName);}}
}
